<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { api, apiError, responseData } from '../../api'
import AdminState from '../../admin/AdminState.vue'

const bookings=ref([]),loading=ref(false),error=ref(''),search=ref(''),status=ref(''),open=ref(false),saving=ref(false),formError=ref('')
const form=reactive({guest_name:'',guest_phone:'',guest_email:'',hotel_id:'',room_type_id:'',room_id:'',check_in:'',check_out:'',adults:1,children:0,total_amount:'',payment_method:'cash',payment_status:'paid',source:'walk_in'})
const filtered=computed(()=>bookings.value.filter(item=>(!status.value||item.status===status.value)&&(!search.value||[item.code,item.booking_code,item.guest_name,item.guest_phone].some(v=>String(v??'').toLowerCase().includes(search.value.toLowerCase())))))
const money=value=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(value||0))
function list(response){const data=responseData(response);return Array.isArray(data)?data:data?.bookings??data?.items??[]}
async function load(){loading.value=true;error.value='';try{bookings.value=list(await api.get('/admin/bookings'))}catch(err){error.value=apiError(err)}finally{loading.value=false}}
async function createBooking(){saving.value=true;formError.value='';try{await api.post('/admin/bookings/counter',{room_type_id:form.room_type_id,room_ids:form.room_id?[form.room_id]:undefined,rooms:form.room_id?undefined:1,guest_name:form.guest_name,guest_email:form.guest_email,guest_phone:form.guest_phone,checkin:form.check_in,checkout:form.check_out,adults:form.adults,children:form.children});open.value=false;await load()}catch(err){formError.value=apiError(err,'Không thể tạo đặt phòng tại quầy.')}finally{saving.value=false}}
onMounted(load)
</script>
<template><section><header class="admin-page-head"><div><h1>Đặt phòng</h1><p>Danh sách đặt chỗ và nghiệp vụ lễ tân</p></div><button class="admin-button" @click="open=true">+ Đặt tại quầy</button></header><div class="admin-card"><div class="admin-toolbar"><input v-model="search" class="admin-input admin-search" type="search" placeholder="Mã đặt phòng, tên hoặc số điện thoại..."/><select v-model="status" class="admin-select"><option value="">Tất cả trạng thái</option><option v-for="item in ['pending','confirmed','checked_in','checked_out','cancelled']" :key="item">{{item}}</option></select><button class="admin-button secondary" @click="load">Làm mới</button></div><AdminState :loading="loading" :error="error" :empty="!loading&&!error&&!filtered.length" empty-text="Không tìm thấy đặt phòng." @retry="load"/><div v-if="!loading&&filtered.length" class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Mã</th><th>Khách hàng</th><th>Nhận / Trả</th><th>Tổng tiền</th><th>Thanh toán</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><strong>{{item.code??item.booking_code}}</strong></td><td>{{item.guest_name}}<br/><small>{{item.guest_phone}}</small></td><td>{{item.check_in??item.checkin}}<br/>{{item.check_out??item.checkout}}</td><td>{{money(item.total_amount??item.total)}}</td><td><span class="admin-badge" :class="item.payment_status">{{item.payment_status??'unpaid'}}</span></td><td><span class="admin-badge" :class="item.status">{{item.status}}</span></td><td><router-link class="admin-button secondary small" :to="`/admin/bookings/${item.id}`">Chi tiết</router-link></td></tr></tbody></table></div></div><div v-if="open" class="admin-modal-backdrop" @click.self="open=false"><form class="admin-modal" @submit.prevent="createBooking"><header class="admin-modal-head"><h2>Đặt phòng tại quầy</h2><button class="admin-modal-close" type="button" @click="open=false">×</button></header><div class="admin-modal-body"><p v-if="formError" class="admin-alert">{{formError}}</p><div class="admin-form-grid"><label class="admin-field"><span>Tên khách</span><input v-model="form.guest_name" class="admin-input" required/></label><label class="admin-field"><span>Điện thoại</span><input v-model="form.guest_phone" class="admin-input" required/></label><label class="admin-field"><span>Email</span><input v-model="form.guest_email" class="admin-input" type="email"/></label><label class="admin-field"><span>ID khách sạn</span><input v-model="form.hotel_id" class="admin-input" type="number" required/></label><label class="admin-field"><span>ID loại phòng</span><input v-model="form.room_type_id" class="admin-input" type="number" required/></label><label class="admin-field"><span>ID phòng (nếu đã xếp)</span><input v-model="form.room_id" class="admin-input" type="number"/></label><label class="admin-field"><span>Ngày nhận</span><input v-model="form.check_in" class="admin-input" type="date" required/></label><label class="admin-field"><span>Ngày trả</span><input v-model="form.check_out" class="admin-input" type="date" required/></label><label class="admin-field"><span>Người lớn</span><input v-model="form.adults" class="admin-input" type="number" min="1" required/></label><label class="admin-field"><span>Trẻ em</span><input v-model="form.children" class="admin-input" type="number" min="0"/></label><label class="admin-field full"><span>Tổng thu tiền mặt</span><input v-model="form.total_amount" class="admin-input" type="number" min="0" required/></label></div><p class="admin-alert" style="margin:15px 0 0;color:#475569;border-color:#dbeafe;background:#eff6ff">Phương thức thanh toán: tiền mặt tại quầy.</p></div><footer class="admin-modal-foot"><button class="admin-button secondary" type="button" @click="open=false">Hủy</button><button class="admin-button" :disabled="saving">{{saving?'Đang tạo...':'Xác nhận đặt phòng'}}</button></footer></form></div></section></template>
